function getRealStatus(c){
 const now=Date.now(),start=new Date(c.start).getTime();
 if(now<start)return {key:"upcoming",label:"Mendatang"};
 if(c.end===null)return {key:"ongoing",label:"Berlangsung"};
 return now<=new Date(c.end).getTime()?{key:"ongoing",label:"Berlangsung"}:{key:"done",label:"Selesai"};
}
function formatStatus(c){const s=getRealStatus(c);return `<span class="status ${s.key}">${icon("dot")}<span>${s.label}</span></span>`}
function renderChallengeList(){
 const list=realChallenges.filter(x=>filter==="all"||getRealStatus(x).key===filter).sort((a,b)=>new Date(b.start)-new Date(a.start)||Number(b.id)-Number(a.id));
 app.querySelector?.("#homeContent");
 document.getElementById("homeContent").innerHTML=`
  <div class="search-wrap"><span class="search-icon">${icon("search")}</span><input id="search" class="search" placeholder="Cari tantangan" autocomplete="off"></div>
  <div class="chips">${[["all","Semua"],["ongoing","Berlangsung"],["upcoming","Mendatang"],["done","Selesai"]].map(([v,l])=>`<button class="chip ${filter===v?"active":""}" data-filter="${v}">${l}</button>`).join("")}</div>
  <div class="list" id="challengeList">${list.map((x,i)=>`<button class="challenge-card" data-index="${i}">${formatStatus(x)}<div class="card-title">Tantangan ${x.id} — ${esc(x.title)}</div><div class="card-desc">${esc(x.description)}</div><div class="card-meta"><div><span class="meta-label">Hadiah</span><span class="meta-value">${esc(x.prize)}</span></div><div><span class="meta-label">Waktu</span><span class="meta-value">${esc(x.endText)}</span></div></div><span class="card-arrow">${icon("arrow")}</span></button>`).join("")||`<div class="empty">Tidak ada tantangan yang ditemukan.</div>`}</div>`;
 document.querySelectorAll(".chip").forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderChallengeList()});
 document.getElementById("search").oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll(".challenge-card").forEach(c=>c.style.display=c.innerText.toLowerCase().includes(q)?"":"none")};
 document.querySelectorAll(".challenge-card").forEach((b,i)=>b.onclick=()=>navigate("detail",{id:list[i].id}));
}
function renderChallengeDetail(c){
 if(!c){goBack();return}
 app.innerHTML=`${backButton()}<div class="detail-status">${formatStatus(c)}</div><h1 class="detail-title">Tantangan ${c.id}<br>${esc(c.title)}</h1><p class="muted">${esc(c.description)}</p>
 <div class="info-grid"><div class="info-cell"><div class="info-label">Waktu mulai</div><div class="info-value">${esc(c.startText)}</div></div><div class="info-cell"><div class="info-label">Waktu selesai</div><div class="info-value">${esc(c.endText)}</div></div><div class="info-cell"><div class="info-label">Hadiah</div><div class="info-value">${esc(c.prize)}</div></div><div class="info-cell"><div class="info-label">Pemenang</div><div class="info-value">${c.winner?esc(c.winner):(c.winnersCount?`${c.winnersCount} orang`:`Tidak ada`)}</div></div></div>
 <section class="section"><div class="section-head"><span class="section-icon">${icon("check")}</span><span>Instruksi</span></div><ol class="detail-list">${c.method.map((x,i)=>`<li><span class="step-icon">${icon(i===0?"compass":"check")}</span><span>${esc(x)}</span></li>`).join("")}</ol></section>
 <section class="section"><div class="section-head"><span class="section-icon">${icon("shield")}</span><span>Syarat & Ketentuan</span></div><ol class="detail-list">${c.rules.map(x=>`<li><span class="step-icon">${icon("info")}</span><span>${esc(x)}</span></li>`).join("")}</ol></section>
 <section class="section"><div class="section-head"><span class="section-icon">${icon("file")}</span><span>Status</span></div><p class="muted">Tantangan ini berasal dari tantangan nyata Tanta dan ditampilkan di Dotous sebagai arsip tantangan nyata.</p></section>`;
 document.getElementById("back").onclick=goBack;
}
function renderRandomChallenge(){
 const last=lastChallenge();
 const result=last||"Siap untuk tantangan?";
 document.getElementById("homeContent").innerHTML=`<div class="random-panel"><div class="random-icon">${icon("spark")}</div><div class="random-kicker">TANTANGAN ACAK</div><div class="random-result" id="randomResult">${esc(result)}</div><div class="random-sub" id="randomSub">Kesempatan hari ini: ${uses()} / 3</div><button class="primary" id="randomBtn">Ambil Tantangan</button></div><p class="random-note">Setiap hasil dipilih menggunakan sumber randomness kriptografis dari browser.</p>`;
 const btn=document.getElementById("randomBtn");
 btn.onclick=()=>{
  const c=pickChallenge();
  const shown=c||lastChallenge();
  if(!shown)return;
  document.getElementById("randomResult").textContent=shown;
  document.getElementById("randomSub").textContent=`Kesempatan hari ini: ${uses()} / 3`;
 };
}
const CHOICE_KEY="dotous-random-choices";
const CHOICE_RESULT_KEY="dotous-random-result";
const SPIN_KEY="dotous-spinner-choices";
const SPIN_RESULT_KEY="dotous-spinner-result";

function loadList(key){
 try{const v=JSON.parse(localStorage.getItem(key)||"[]");return Array.isArray(v)?v.map(x=>String(x)):[]}catch{return []}
}
function saveList(key,list){localStorage.setItem(key,JSON.stringify(list))}
function loadValue(key){return localStorage.getItem(key)||""}
function saveValue(key,value){localStorage.setItem(key,value||"")}
function normalizeChoices(values){return values.map(v=>String(v).trim()).filter(Boolean)}

function renderChoiceRows(){
 const form=document.getElementById("randomForm");
 if(!form)return;
 const choices=loadList(CHOICE_KEY);
 const values=choices.length?choices:["",""];
 form.innerHTML=values.map((value,i)=>`<div class="choice-row"><input class="choice-input" data-choice data-index="${i}" value="${esc(value)}" placeholder="Pilihan ${i+1}" autocomplete="off"><button class="choice-remove" type="button" data-remove-choice="${i}" aria-label="Hapus pilihan ${i+1}">${icon("close")}</button></div>`).join("");
 form.querySelectorAll("[data-choice]").forEach(input=>{
  input.addEventListener("input",()=>{
   const vals=[...form.querySelectorAll("[data-choice]")].map(x=>x.value);
   saveList(CHOICE_KEY,vals);
  });
 });
 form.querySelectorAll("[data-remove-choice]").forEach(btn=>btn.onclick=()=>{
  const vals=[...form.querySelectorAll("[data-choice]")].map(x=>x.value);
  const index=Number(btn.dataset.removeChoice);
  vals.splice(index,1);
  if(vals.length<2)while(vals.length<2)vals.push("");
  saveList(CHOICE_KEY,vals);
  renderChoiceRows();
 });
}

function randomChoicePick(){
 const values=normalizeChoices(loadList(CHOICE_KEY));
 const result=document.getElementById("pickResult");
 if(values.length<2){result.innerHTML=`<div class="empty">Masukkan minimal 2 pilihan.</div>`;return}
 const pick=values[secureRandomInt(values.length)];
 saveValue(CHOICE_RESULT_KEY,pick);
 result.innerHTML=`<div class="random-choice-result"><div class="eyebrow">HASIL</div><h2>${esc(pick)}</h2><p>Terpilih secara acak dari ${values.length} pilihan.</p></div>`;
}

function spinnerVisualChoices(displayValues){
 const wheel=document.getElementById("spinnerWheel");
 if(!wheel)return;
 const values=displayValues||secureShuffle(normalizeChoices(loadList(SPIN_KEY)));
 const palette=["#111827","#5148d8","#8b8df0","#e8eaf1","#303b58","#766fe5","#b8b9f7","#d5d8e2"];
 const n=values.length;
 if(!n){wheel.style.background="conic-gradient(#eef0f4 0deg 360deg)";wheel.innerHTML="";return}
 const slice=360/n;
 const stops=values.map((_,i)=>`${palette[i%palette.length]} ${i*slice}deg ${(i+1)*slice}deg`).join(",");
 wheel.style.background=`conic-gradient(${stops})`;
 // Draw every entered option directly on its own wheel sector.
 // The same option order is preserved; only the winner is selected randomly.
 wheel.innerHTML=values.map((value,i)=>{
  const angle=(i+.5)*slice;
  const light=[3,6,7].includes(i%palette.length);
  const fontSize=n>24?6:n>16?7: n>10?8: n>7?9:10;
  return `<span class="spinner-label" title="${esc(value)}" style="--angle:${angle}deg;--radius:${Math.round((wheel.clientWidth||290)*0.31)}px;--label-color:${light?"#252b38":"#ffffff"};font-size:${fontSize}px">${esc(value)}</span>`;
 }).join("");
}
function renderSpinner(){
 let choices=loadList(SPIN_KEY);
 if(!choices.length){choices=["",""];saveList(SPIN_KEY,choices)}
 const result=loadValue(SPIN_RESULT_KEY);
 const active=normalizeChoices(choices);
 const resultMarkup=result?`<div class="eyebrow">HASIL SPINNER</div><strong>${esc(result)}</strong>`:`<div class="eyebrow">SIAP UNTUK DIACAK?</div><p>Isi minimal 2 nama atau pilihan, lalu putar spinner.</p>`;
 const choiceMarkup=choices.map((x,i)=>`<div class="saved-choice"><input data-spin-input data-spin-index="${i}" value="${esc(x)}" placeholder="Pilihan ${i+1}" autocomplete="off"><button type="button" data-remove-spin="${i}" aria-label="Hapus pilihan ${i+1}">${icon("close")}</button></div>`).join("");
 app.querySelector(".random-tab-content").innerHTML=`
  <div class="spinner-card">
   <div class="spinner-wheel-wrap"><div class="spinner-pointer"></div><div class="spinner-wheel" id="spinnerWheel" aria-label="Roda spinner"></div><div class="spinner-center" aria-label="Logo Dotous"><img src="assets/logo.png" alt="Dotous"></div></div>
   <div class="spinner-result ${result?"has-result":""}" id="spinnerResult">${resultMarkup}</div>
   <button class="primary random-submit" id="spinBtn" ${active.length<2?"disabled":""}>Putar spinner</button>
  </div>
  <div class="spinner-choice-list">
   <div class="choice-list-head"><div><div class="eyebrow">DAFTAR PILIHAN</div><strong id="spinCount">${active.length} pilihan terisi</strong></div><button class="reset-button reset-box" id="resetSpinner">${icon("refresh")}<span>Ulangi</span></button></div>
   <div id="spinnerChoices">${choiceMarkup}</div>
   <button class="add-choice" id="addSpinChoice">${icon("plus")}<span>Tambah pilihan</span></button>
  </div>`;
 spinnerVisualChoices(secureShuffle(active));
 bindSpinner();
}
function bindSpinner(){
 document.querySelectorAll("[data-spin-input]").forEach(input=>input.addEventListener("input",()=>{
  const choices=loadList(SPIN_KEY);choices[Number(input.dataset.spinIndex)]=input.value;saveList(SPIN_KEY,choices);
  spinnerVisualChoices();
  const count=normalizeChoices(choices).length;
  document.getElementById("spinCount").textContent=`${count} pilihan terisi`;
  document.getElementById("spinBtn").disabled=count<2;
 }));
 document.getElementById("addSpinChoice").onclick=()=>{
  const choices=loadList(SPIN_KEY);choices.push("");saveList(SPIN_KEY,choices);renderSpinner();
  const fields=document.querySelectorAll("[data-spin-input]");
  if(fields.length)fields[fields.length-1].focus();
 };
 document.querySelectorAll("[data-remove-spin]").forEach(btn=>btn.onclick=()=>{
  const choices=loadList(SPIN_KEY);choices.splice(Number(btn.dataset.removeSpin),1);
  if(choices.length<2)while(choices.length<2)choices.push("");
  saveList(SPIN_KEY,choices);
  renderSpinner();
 });
 const reset=document.getElementById("resetSpinner");
 reset.onclick=()=>{saveList(SPIN_KEY,["",""]);saveValue(SPIN_RESULT_KEY,"");renderSpinner()};
 document.getElementById("spinBtn").onclick=spinSpinner;
}

function spinSpinner(){
 const choices=secureShuffle(normalizeChoices(loadList(SPIN_KEY)));
 if(choices.length<2)return;
 const wheel=document.getElementById("spinnerWheel");
 const button=document.getElementById("spinBtn");
 if(!wheel||!button||button.disabled)return;
 // Choose the winning entry once with unbiased CSPRNG. The wheel animation
 // is then calculated to stop on that exact sector, not a separate result.
 // Sektor diacak ulang setiap putaran, lalu pemenang dipilih merata dari susunan itu.
 spinnerVisualChoices(choices);
 const winnerIndex=secureRandomInt(choices.length);
 const pick=choices[winnerIndex];
 const slice=360/choices.length;
 const landingAngle=(360-((winnerIndex+.5)*slice)%360)%360;
 const extraTurns=5+secureRandomInt(5);
 const currentRotation=Number(wheel.dataset.rotation||0);
 const targetRotation=currentRotation+(extraTurns*360)+landingAngle;
 saveValue(SPIN_RESULT_KEY,pick);
 button.disabled=true;
 wheel.style.transition="transform 5.2s cubic-bezier(.12,.72,.12,1)";
 wheel.style.transform=`rotate(${targetRotation}deg)`;
 wheel.dataset.rotation=String(targetRotation);
 wheel.addEventListener("transitionend",()=>{
  renderSpinner();
  openSpinPopup(pick);
 },{once:true});
}

function openSpinPopup(value){
 const old=document.getElementById("spinPopup");if(old)old.remove();
 const popup=document.createElement("div");popup.id="spinPopup";popup.className="modal-backdrop";
 popup.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="spinPopupTitle"><button class="modal-close" id="spinCancelTop" aria-label="Tutup">${icon("close")}</button><div class="eyebrow">HASIL SPINNER</div><h2 id="spinPopupTitle">${esc(value)}</h2><p>Pilihan ini sudah didapat. Mau menghapusnya dari daftar spinner?</p><div class="modal-actions"><button class="modal-secondary" id="spinCancel">Batalkan</button><button class="modal-primary" id="spinDelete">Hapus ${esc(value)}</button></div></div>`;
 document.body.appendChild(popup);
 const close=()=>popup.remove();
 document.getElementById("spinCancel").onclick=close;
 document.getElementById("spinCancelTop").onclick=close;
 document.getElementById("spinDelete").onclick=()=>{
  const choices=loadList(SPIN_KEY).filter(x=>x!==value);
  while(choices.length<2)choices.push("");
  saveList(SPIN_KEY,choices);close();renderSpinner();
 };
 popup.onclick=e=>{if(e.target===popup)close()};
}

function renderRandom(){
 const tab=localStorage.getItem("dotous-random-tab")||"choices";
 app.innerHTML=`${backButton()}<section class="page-title"><h1>Pilih Random</h1></section><div class="tabs random-tabs"><button class="tab ${tab==="choices"?"active":""}" data-random-tab="choices">Pilihan</button><button class="tab ${tab==="spinner"?"active":""}" data-random-tab="spinner">Spinner</button></div><div class="random-tab-content"></div>`;
 document.getElementById("back").onclick=goBack;
 document.querySelectorAll("[data-random-tab]").forEach(b=>b.onclick=()=>{localStorage.setItem("dotous-random-tab",b.dataset.randomTab);renderRandom()});
 if(tab==="spinner"){renderSpinner();return}
 const saved=loadList(CHOICE_KEY);
 app.querySelector(".random-tab-content").innerHTML=`<div class="random-form" id="randomForm"></div><div class="choice-actions"><button class="add-choice" id="addChoice">${icon("plus")}<span>Tambah pilihan</span></button><button class="reset-button reset-box" id="resetChoices">${icon("refresh")}<span>Ulangi</span></button></div><button id="choose" class="primary random-submit">Acak</button><div id="pickResult"></div>`;
 renderChoiceRows();
 const previous=loadValue(CHOICE_RESULT_KEY);
 if(previous){document.getElementById("pickResult").innerHTML=`<div class="random-choice-result"><div class="eyebrow">HASIL</div><h2>${esc(previous)}</h2><p>Hasil terakhir tetap tersimpan.</p></div>`}
 document.getElementById("addChoice").onclick=()=>{const vals=loadList(CHOICE_KEY);vals.push("");saveList(CHOICE_KEY,vals);renderChoiceRows();const fields=document.querySelectorAll("[data-choice]");fields[fields.length-1].focus()};
 document.getElementById("resetChoices").onclick=()=>{saveList(CHOICE_KEY,["",""]);saveValue(CHOICE_RESULT_KEY,"");renderRandom()};
 document.getElementById("choose").onclick=randomChoicePick;
}
